CREATE TABLE faqs (id UUID PRIMARY KEY, question TEXT NOT NULL, answer TEXT NOT NULL, sort_order INT NOT NULL DEFAULT 0);
CREATE TABLE posts (id UUID PRIMARY KEY, title VARCHAR(200) NOT NULL, slug VARCHAR(240) NOT NULL UNIQUE, category VARCHAR(30) NOT NULL,
  body TEXT NOT NULL, premium BOOLEAN NOT NULL DEFAULT FALSE, published BOOLEAN NOT NULL DEFAULT FALSE, author VARCHAR(120) NOT NULL,
  seo_title VARCHAR(200), seo_description VARCHAR(300), views BIGINT NOT NULL DEFAULT 0, published_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE reviews (id UUID PRIMARY KEY, user_id UUID NOT NULL UNIQUE REFERENCES users(id), author_name VARCHAR(120) NOT NULL,
  rating INT NOT NULL CHECK (rating BETWEEN 1 AND 5), body VARCHAR(1500) NOT NULL, status VARCHAR(10) NOT NULL DEFAULT 'PENDING',
  verified BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE contact_inquiries (id UUID PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL, mobile VARCHAR(20),
  subject VARCHAR(200) NOT NULL, message VARCHAR(3000) NOT NULL, status VARCHAR(10) NOT NULL DEFAULT 'NEW', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
